import{_ as a,D as l,c as d,j as t,a as e,I as i,a2 as s,o as c}from"./chunks/framework.DdOM6S6U.js";const T=JSON.parse('{"title":"ActiveTableItem","description":"","frontmatter":{"sidebarPos":10,"sidebarTitle":"Active Table Item"},"headers":[],"relativePath":"guide/components/labs/active-table-item.md","filePath":"guide/components/labs/active-table-item.md","lastUpdated":1777448653000}'),n={name:"guide/components/labs/active-table-item.md"},r={id:"activetableitem",tabindex:"-1"},p=t("a",{class:"header-anchor",href:"#activetableitem","aria-label":'Permalink to "ActiveTableItem <Badge type="warning" text="experimental" />"'},"​",-1),h=s(`<p><code>ActiveTableItem</code> provides a two-phase drill-down UI for a selected table row:</p><ol><li><strong>Selection modal</strong> — a <code>ue-modal</code> dialog showing a grid of labelled blocks. The user clicks a block to select a sub-section.</li><li><strong>Detail panel</strong> — once a block is selected, the modal closes and an inline <code>ue-table</code> renders the item&#39;s details alongside any additional elements configured for that block.</li></ol><p>The component delegates its logic entirely to <code>useActiveTableItem</code> and <code>makeActiveTableItemProps</code> from the internal <code>__hooks</code> module.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This component is designed for use inside table row-click handlers. It is not a general-purpose component.</p></div><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User clicks a row</span></span>
<span class="line"><span>  → ActiveTableItem mounts with item data</span></span>
<span class="line"><span>  → Modal opens showing block options</span></span>
<span class="line"><span>  → User clicks a block (selectNested)</span></span>
<span class="line"><span>    → modalActive = false, activeBlock = selected block</span></span>
<span class="line"><span>    → ue-table renders item details for that block</span></span>
<span class="line"><span>    → ue-recursive-stuff renders block.elements below the table</span></span>
<span class="line"><span>  → User clicks ✕ to close (closeItemDetails)</span></span>
<span class="line"><span>    → activeBlock = null</span></span></code></pre></div><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><p>Props are defined by <code>makeActiveTableItemProps()</code> from the <code>__hooks</code> module. The exact shape depends on the hook implementation, but typically includes:</p><table><thead><tr><th>Prop</th><th>Description</th></tr></thead><tbody><tr><td><code>item</code></td><td>The full row data object for the selected record</td></tr><tr><td><code>itemData</code></td><td>Array of block definitions. Each block controls what appears in the modal and what is rendered in the detail panel.</td></tr><tr><td><code>tableHeaders</code></td><td>Column definitions forwarded to the detail <code>ue-table</code></td></tr></tbody></table><h2 id="block-definition" tabindex="-1">Block definition <a class="header-anchor" href="#block-definition" aria-label="Permalink to &quot;Block definition&quot;">​</a></h2><p>Each entry in <code>itemData</code> configures one selectable block in the modal:</p><table><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td><code>String</code></td><td>Label shown on the block button</td></tr><tr><td><code>elements</code></td><td><code>Array</code></td><td><code>ue-recursive-stuff</code> configuration rendered below the detail table</td></tr><tr><td><code>clickBlock</code></td><td><code>Object</code></td><td>Optional. If present, overrides the block button with a custom layout. <code>clickBlock.col</code> sets the <code>v-col</code> bindings; <code>clickBlock.elements</code> is passed to <code>ue-recursive-stuff</code> instead of a plain button.</td></tr></tbody></table><h2 id="detail-table" tabindex="-1">Detail table <a class="header-anchor" href="#detail-table" aria-label="Permalink to &quot;Detail table&quot;">​</a></h2><p>The inline <code>ue-table</code> is rendered with:</p><ul><li><code>is-row-editing: false</code></li><li><code>create-on-modal: false</code> / <code>edit-on-modal: false</code></li><li><code>row-actions: []</code></li><li><code>items-per-page: 1</code> (single-item view)</li><li>Footer, form, and full-screen chrome are hidden</li><li>A close (<code>✕</code>) button in <code>#headerRight</code> calls <code>closeItemDetails()</code></li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>ignore-formatters: [&#39;activate&#39;]</code> is passed to prevent the activate formatter from rendering on the detail table.</li><li>The detail panel only shows when <code>item</code> is set, <code>modalActive</code> is <code>false</code>, and <code>activeBlock</code> is non-null.</li><li>Customise the block layout using <code>clickBlock.elements</code> and <code>ue-recursive-stuff</code> configuration objects.</li></ul>`,17);function b(m,u,f,k,v,g){const o=l("Badge");return c(),d("div",null,[t("h1",r,[e("ActiveTableItem "),i(o,{type:"warning",text:"experimental"}),e(),p]),h])}const w=a(n,[["render",b]]);export{T as __pageData,w as default};
